import React, { useState } from "react";
import { useForm, Controller, SubmitHandler } from "react-hook-form";
import { yupResolver } from "@hookform/resolvers/yup";
import * as yup from "yup";
import {
  TextField,
  Button,
  FormControl,
  FormLabel,
  FormControlLabel,
  RadioGroup,
  Radio,
  Checkbox,
  FormGroup,
  Box,
  Typography,
  TextareaAutosize,
} from "@mui/material";
import { useTranslation } from "react-i18next";
import { db } from "../../firebaseConfig"; // Ajusta la ruta según tu estructura
import { collection, addDoc, Timestamp } from "firebase/firestore";
import emailjs from "@emailjs/browser";

const phoneRegExp = /^\(\d{3}\) \d{3} \d{4}$/;

const schema: yup.ObjectSchema<FormData> = yup.object({
  fullName: yup.string().required("Full name is required"),
  email: yup.string().email("Invalid email").required("Email is required"),
  phone: yup
    .string()
    .matches(phoneRegExp, "Phone must be in format numeric only (123) 456 7890")
    .required("Phone is required"),
  message: yup.string().required("Message is required"),
}) as yup.ObjectSchema<FormData>;

type FormData = {
  fullName: string;
  email: string;
  phone: string;
  message: string;
};

export default function ContactForm() {
  const [sending, setSending] = useState(false);
  const [submitted, setSubmitted] = useState(false);
  const { t } = useTranslation();

  const {
    control,
    handleSubmit,
    reset,
    formState: { errors },
  } = useForm<FormData>({
    resolver: yupResolver(schema),
    defaultValues: {
      fullName: "",
      email: "",
      phone: "",
      message: "",
    },
  });

  const onSubmit: SubmitHandler<FormData> = async (data) => {
    setSending(true);
    try {
      // 1. Save to Firestore
      const docRef = await addDoc(collection(db, "contactMessages"), {
        ...data,
        createdAt: Timestamp.now(),
      });
      // 2. Send email via EmailJS
      const serviceId = process.env.GATSBY_EMAILJS_SERVICE_ID;
      const templateId = process.env.GATSBY_EMAILJS_TEMPLATE_ID;
      const publicKey = process.env.GATSBY_EMAILJS_PUBLIC_KEY;

      if (!serviceId || !templateId || !publicKey) {
        console.error("Missing EmailJS environment variables");
        setSending(false);
        return;
      }

      await emailjs.send(
        serviceId,
        templateId,
        {
          fullName: data.fullName,
          email: data.email,
          phone: data.phone,
          message: data.message,
        },
        publicKey
      );
      reset();
      setSubmitted(true);
    } catch (error) {
      console.error("Error submitting form:", error);
    } finally {
      setSending(false);
    }
  };

  return (
    <Box
      component="form"
      onSubmit={handleSubmit(onSubmit)}
      className="w-full sm:w-[400px]"
    >
      {submitted ? (
        <Box className="flex flex-col items-center mt-12 p-4 text-center">
          <Typography variant="h6" className="text-DeepSea head-4 mb-2">
            {t("contact.form.thankYou") || "Thank you for your message!"}
          </Typography>
          <Typography className="text-DarkSea body-3 mb-4">
            {t("contact.form.confirmation") ||
              "We will get back to you shortly."}
          </Typography>
          <Button
            onClick={() => {
              reset();
              setSubmitted(false);
            }}
            className="bg-DeepSea/10 rounded-md py-3 px-6"
          >
            <span className="text-DeepSea/80">
              {t("contact.form.backToForm") || "Back to Form"}
            </span>
          </Button>
        </Box>
      ) : (
        <>
          <Typography className="body-3 mb-6">{t("contact.subtitle")}</Typography>

          <Controller
            name="fullName"
            control={control}
            render={({ field }) => (
              <TextField
                {...field}
                label={t("contact.form.name") || "Name"}
                placeholder={t("contact.form.name") || "Name"}
                fullWidth
                margin="dense"
                error={!!errors.fullName}
                helperText={errors.fullName?.message}
                className="body-4 bg-DeepSea/10"
                variant="outlined"
                InputProps={{
                  classes: {
                    root: "rounded-md focus-within:border-Oatmeal",
                    notchedOutline: "border border-DeepSea",
                    input: "placeholder-DeepSea body-4 text-DeepSea",
                  },
                }}
                FormHelperTextProps={{
                  className: "text-CoralRed menu mt-1",
                }}
              />
            )}
          />

          <Controller
            name="email"
            control={control}
            render={({ field }) => (
              <TextField
                {...field}
                label="Email"
                type="email"
                fullWidth
                margin="dense"
                error={!!errors.email}
                helperText={errors.email?.message}
                className="body-4 bg-DeepSea/10"
                variant="outlined"
                InputProps={{
                  classes: {
                    root: "rounded-md focus-within:border-Oatmeal",
                    notchedOutline: "border border-DeepSea",
                    input: "placeholder-DeepSea body-4 text-DeepSea",
                  },
                }}
                FormHelperTextProps={{
                  className: "text-CoralRed menu mt-1",
                }}
              />
            )}
          />

          <Controller
            name="phone"
            control={control}
            rules={{
              validate: (value) => {
                const digitsOnly = value.replace(/\D/g, "");
                return (
                  digitsOnly.length === 10 ||
                  t("form.errors.phone") ||
                  "Invalid phone number"
                );
              },
            }}
            render={({ field: { onChange, value, ...field } }) => (
              <TextField
                {...field}
                value={value}
                onChange={(e) => {
                  const digits = e.target.value.replace(/\D/g, "").slice(0, 10);
                  const formatted = digits.replace(
                    /(\d{0,3})(\d{0,3})(\d{0,4})/,
                    (_, p1, p2, p3) =>
                      `${p1 ? `(${p1}` : ""}${p2 ? `) ${p2}` : ""}${
                        p3 ? ` ${p3}` : ""
                      }`
                  );
                  onChange(formatted);
                }}
                label="Phone"
                placeholder="(123) 456 7890"
                fullWidth
                margin="dense"
                error={!!errors.phone}
                helperText={errors.phone?.message}
                className="body-4 bg-DeepSea/10"
                variant="outlined"
                InputProps={{
                  classes: {
                    root: "rounded-md focus-within:border-Oatmeal",
                    notchedOutline: "border border-DeepSea",
                    input: "placeholder-DeepSea body-4 text-DeepSea",
                  },
                }}
                FormHelperTextProps={{
                  className: "text-CoralRed menu mt-1",
                }}
              />
            )}
          />

          <Controller
            name="message"
            control={control}
            render={({ field }) => (
              <TextField
                {...field}
                label={t("contact.form.message") || "Message"}
                placeholder={t("contact.form.message") || "Message"}
                fullWidth
                multiline
                rows={4}
                margin="dense"
                error={!!errors.message}
                helperText={errors.message?.message}
                className="body-4 bg-DeepSea/10"
                variant="outlined"
                InputProps={{
                  classes: {
                    root: "rounded-md focus-within:border-Oatmeal",
                    notchedOutline: "border border-DeepSea",
                    input: "placeholder-DeepSea body-4 text-DeepSea",
                  },
                }}
              />
            )}
          />

          <Button
            type="submit"
            className="bg-DeepSea/10 w-full rounded-md py-5 mt-2 "
          >
            <span className="text-DeepSea/80">
              {sending ? t("contact.form.sending") : t("contact.form.send")}
            </span>
          </Button>
        </>
      )}
    </Box>
  );
}
